begin;
-- B0 is a schema/security reconciliation only; it creates no HTTP endpoints.
-- Bounded worker role. Never grant it to authenticated/anon or to a BYPASSRLS role.
do $$ begin
 if not exists(select 1 from pg_roles where rolname='selvora_service') then create role selvora_service nologin noinherit; end if;
 if exists(select 1 from pg_roles where rolname='selvora_service' and (rolsuper or rolbypassrls or rolcanlogin or rolinherit or rolcreaterole or rolcreatedb or rolreplication)) then raise exception 'Unsafe preexisting worker role' using errcode='55000'; end if;
 if exists(select 1 from pg_auth_members m join pg_roles r on r.oid=m.member join pg_roles w on w.oid=m.roleid where w.rolname='selvora_service' and r.rolname in ('authenticated','anon','service_role')) then raise exception 'Unsafe worker membership' using errcode='55000';end if;
end $$;
grant usage on schema public,auth to selvora_service;
grant execute on function auth.uid() to selvora_service;
create function public.service_vendor(p_vendor uuid) returns boolean language sql stable set search_path='' as $$
 select current_user='selvora_service' and p_vendor=nullif(current_setting('app.vendor_id',true),'')::uuid;
$$;
revoke all on function public.service_vendor(uuid) from public;
grant execute on function public.service_vendor(uuid) to selvora_service;
-- Existing data is migrated explicitly, not discarded.
alter table public.customers add column notes text not null default '' check(length(notes)<=2000), add column tags text[] not null default '{}' check(cardinality(tags)<=10), add column flagged boolean not null default false, add column city text, add column updated_at timestamptz not null default now();
alter table public.customers add constraint customer_city check(city is null or city in ('Lagos','Abuja','Ibadan'));
alter table public.vendor_members add column name text not null default '', add column status text not null default 'active' check(status in ('active','suspended'));
alter table public.conversations add column stage text not null default 'new' check(stage in ('new','interested','ready_to_pay','paid','cold')), add column status text not null default 'open' check(status in ('open','resolved')), add column assigned_member_id uuid, add column thread_url text, add column suggested_replies text[] not null default '{}', add column last_message_id uuid, add column updated_at timestamptz not null default now(), add column revision bigint not null default 1 check(revision>0);
alter table public.conversations add foreign key(vendor_id,assigned_member_id) references public.vendor_members(vendor_id,id);
alter table public.messages add column kind text not null default 'text' check(kind in ('text','voice')), add column voice_transcript text, add column voice_duration_seconds integer check(voice_duration_seconds>0), add column audio_storage_key text, add column english_summary text, add column product_snapshot jsonb, add column order_snapshot jsonb, add column revision bigint not null default 1 check(revision>0), add column updated_at timestamptz not null default now();
alter table public.messages add constraint messages_thread_identity unique(vendor_id,conversation_id,id);
alter table public.messages drop constraint messages_status_check;
alter table public.messages add constraint messages_status_check check(status in ('received','draft','pending_approval','blocked','queued','sending','sent','delivered','read','failed'));
alter table public.conversations add foreign key(vendor_id,id,last_message_id) references public.messages(vendor_id,conversation_id,id);
alter table public.products add column category text not null default 'Custom' check(category in ('Fashion','Shoes','Beauty','Food & drink','Home','Accessories','Services','Custom')), add column details jsonb not null default '{"sizes":[],"portion":"","prepMinutes":null,"durationMinutes":null}' check(jsonb_typeof(details)='object'), add column low_stock_threshold integer not null default 5 check(low_stock_threshold>=0), add column archived boolean not null default false, add column revision bigint not null default 1 check(revision>0), add column updated_at timestamptz not null default now();
alter table public.product_variants add column revision bigint not null default 1 check(revision>0);
alter table public.orders drop constraint orders_status_check;
update public.orders set status=case status when 'pending' then case when payment_status='paid' then 'paid' else 'draft' end when 'confirmed' then case when payment_status='paid' then 'preparing' else 'awaiting_payment' end when 'fulfilled' then case when payment_status='paid' then 'delivered' else 'awaiting_payment' end else status end;
alter table public.orders alter column status set default 'draft';
alter table public.orders add constraint orders_status_check check(status in ('draft','awaiting_payment','paid','preparing','out_for_delivery','delivered','cancelled'));
alter table public.orders add column conversation_id uuid, add column delivery_address text not null default '', add column payment_screenshot_received boolean not null default false, add column payment_link text, add column paid_at timestamptz, add column revision bigint not null default 1 check(revision>0), add column updated_at timestamptz not null default now();
update public.orders set paid_at=created_at where payment_status='paid';
alter table public.orders add foreign key(vendor_id,conversation_id) references public.conversations(vendor_id,id);
alter table public.orders add constraint order_paid_state check(status not in ('paid','preparing','out_for_delivery','delivered') or payment_status='paid');
alter table public.order_items add column name_snapshot text not null default '', add column variant_name_snapshot text;
update public.order_items i set name_snapshot=p.name from public.products p where p.vendor_id=i.vendor_id and p.id=i.product_id;
update public.order_items i set variant_name_snapshot=v.name from public.product_variants v where v.vendor_id=i.vendor_id and v.id=i.variant_id;
alter table public.approvals add column confidence numeric not null default 0 check(confidence>=0 and confidence<=1), add column holding_reply_sent_at timestamptz, add column decided_at timestamptz, add column decided_by uuid, add column revision bigint not null default 1 check(revision>0);
alter table public.approvals add foreign key(vendor_id,decided_by) references public.vendor_members(vendor_id,id);
-- Also verify that the approval's message belongs to its stated conversation.
alter table public.approvals add foreign key(vendor_id,conversation_id,message_id) references public.messages(vendor_id,conversation_id,id);
alter table public.channel_accounts drop constraint channel_accounts_status_check;
alter table public.channel_accounts add constraint channel_accounts_status_check check(status in ('connected','disconnected','expired','error')), add column own_account boolean not null default true check(own_account), add column updated_at timestamptz not null default now();

create table public.business_settings (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), unique(vendor_id), auto_intents text[] not null default array['greeting','price','availability','variants','delivery_info','order_status','alternatives'] check(auto_intents <@ array['greeting','price','availability','variants','delivery_info','order_status','alternatives']::text[]), reply_languages text[] not null default array['en','pcm'] check(cardinality(reply_languages)>0 and reply_languages <@ array['en','pcm']::text[]), hours_enabled boolean not null default false, timezone text not null default 'Africa/Lagos' check(timezone='Africa/Lagos'), away_message text not null default '' check(length(away_message)<=500), revision bigint not null default 1 check(revision>0), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.business_hours (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), day smallint not null check(day between 0 and 6), closed boolean not null default false, opens time not null default '09:00', closes time not null default '18:00', check(closed or opens<closes), unique(vendor_id,day), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.delivery_fees (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), city text not null check(city in ('Lagos','Abuja','Ibadan')), fee_kobo bigint not null check(fee_kobo>=0), unique(vendor_id,city), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.member_preferences (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), member_id uuid not null, low_data boolean not null default false, dark_mode boolean not null default false, language text not null default 'en' check(language in ('en','pcm')), ready_to_pay boolean not null default true, needs_you boolean not null default true, unique(vendor_id,member_id), foreign key(vendor_id,member_id) references public.vendor_members(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.conversation_reads (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), conversation_id uuid not null, member_id uuid not null, last_read_at timestamptz not null default now(), unique(vendor_id,conversation_id,member_id), foreign key(vendor_id,member_id) references public.vendor_members(vendor_id,id), foreign key(vendor_id,conversation_id) references public.conversations(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.product_photos (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), product_id uuid not null, storage_key text not null, name text not null, position smallint not null check(position between 0 and 9), width integer check(width>0), height integer check(height>0), unique(vendor_id,product_id,position), foreign key(vendor_id,product_id) references public.products(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.catalogue_drafts (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), member_id uuid not null, request_key text not null, drafts jsonb not null check(jsonb_typeof(drafts)='array'), expires_at timestamptz not null, unique(vendor_id,request_key), foreign key(vendor_id,member_id) references public.vendor_members(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.typed_proposals (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), member_id uuid not null, input_text text not null check(length(input_text) between 1 and 4000), candidates jsonb not null check(jsonb_typeof(candidates)='array'), selected_product_id uuid, expected_revision bigint check(expected_revision>0), status text not null default 'pending' check(status in ('pending','confirmed','expired')), expires_at timestamptz not null, foreign key(vendor_id,member_id) references public.vendor_members(vendor_id,id), foreign key(vendor_id,selected_product_id) references public.products(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.team_invitations (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), email text not null check(email=lower(btrim(email))), name text not null check(length(name) between 1 and 80), role text not null check(role in ('manager','agent')), invited_by uuid not null, accepted_member_id uuid, status text not null default 'pending' check(status in ('pending','accepted','revoked','expired')), expires_at timestamptz not null, foreign key(vendor_id,invited_by) references public.vendor_members(vendor_id,id), foreign key(vendor_id,accepted_member_id) references public.vendor_members(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.invitation_secrets (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), invitation_id uuid not null, token_hash text not null check(token_hash ~ '^[0-9a-f]{64}$'), unique(vendor_id,invitation_id), foreign key(vendor_id,invitation_id) references public.team_invitations(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.customer_identities (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), customer_id uuid not null, channel_account_id uuid not null, external_identity_hash text not null check(external_identity_hash ~ '^[0-9a-f]{64}$'), external_identity_ciphertext bytea not null check(octet_length(external_identity_ciphertext)>16), key_version text not null, verified_at timestamptz, unique(vendor_id,channel_account_id,external_identity_hash), foreign key(vendor_id,customer_id) references public.customers(vendor_id,id), foreign key(vendor_id,channel_account_id) references public.channel_accounts(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.followup_settings (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), unique(vendor_id), enabled boolean not null default false, after_hours integer not null default 48 check(after_hours between 24 and 720), style text not null default 'friendly' check(style in ('friendly','professional','Pidgin-friendly')), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.followups (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), conversation_id uuid not null, customer_id uuid not null, scheduled_at timestamptz not null, sent_at timestamptz, status text not null default 'scheduled' check(status in ('scheduled','sent','cancelled','failed')), message_style text not null check(message_style in ('friendly','professional','Pidgin-friendly')), content text not null check(length(content) between 1 and 4000), consent_at timestamptz, opt_out_at timestamptz, dedupe_key text not null, unique(vendor_id,dedupe_key), check((status='sent')=(sent_at is not null)), foreign key(vendor_id,conversation_id) references public.conversations(vendor_id,id), foreign key(vendor_id,customer_id) references public.customers(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.moderation_flags (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), message_id uuid not null, reason text not null check(length(reason) between 1 and 500), status text not null default 'flagged' check(status in ('flagged','cleared','blocked')), decided_by uuid, decided_at timestamptz, foreign key(vendor_id,message_id) references public.messages(vendor_id,id), foreign key(vendor_id,decided_by) references public.vendor_members(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.blocked_identities (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), identity_id uuid not null, flag_id uuid, blocked_by uuid, active boolean not null default true, unique(vendor_id,identity_id), foreign key(vendor_id,identity_id) references public.customer_identities(vendor_id,id), foreign key(vendor_id,flag_id) references public.moderation_flags(vendor_id,id), foreign key(vendor_id,blocked_by) references public.vendor_members(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.restock_requests (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), product_id uuid not null, variant_id uuid, customer_id uuid not null, status text not null default 'waiting' check(status in ('waiting','notified','cancelled')), notified_at timestamptz, consent_at timestamptz, check((status='notified')=(notified_at is not null)), foreign key(vendor_id,product_id) references public.products(vendor_id,id), foreign key(vendor_id,product_id,variant_id) references public.product_variants(vendor_id,product_id,id), foreign key(vendor_id,customer_id) references public.customers(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.notifications (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), member_id uuid not null, conversation_id uuid, approval_id uuid, kind text not null check(kind in ('ready_to_pay','needs_you','restock','system')), read_at timestamptz, dedupe_key text not null, unique(vendor_id,member_id,dedupe_key), foreign key(vendor_id,member_id) references public.vendor_members(vendor_id,id), foreign key(vendor_id,conversation_id) references public.conversations(vendor_id,id), foreign key(vendor_id,approval_id) references public.approvals(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.channel_tokens (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), channel_account_id uuid not null, ciphertext bytea not null check(octet_length(ciphertext)>16), key_version text not null, expires_at timestamptz, revoked_at timestamptz, unique(vendor_id,channel_account_id), foreign key(vendor_id,channel_account_id) references public.channel_accounts(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.channel_attempts (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), channel_account_id uuid not null, state_hash text not null check(state_hash ~ '^[0-9a-f]{64}$'), status text not null default 'pending' check(status in ('pending','completed','expired','cancelled')), expires_at timestamptz not null, foreign key(vendor_id,channel_account_id) references public.channel_accounts(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.helper_links (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), code_hash text not null check(code_hash ~ '^[0-9a-f]{64}$'), status text not null default 'pending' check(status in ('pending','linked','expired','invalidated')), expires_at timestamptz not null, attempts smallint not null default 0 check(attempts between 0 and 5), linked_at timestamptz, helper_number_ciphertext bytea, key_version text, created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.billing_accounts (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), unique(vendor_id), plan text not null default 'starter' check(plan in ('starter','growth')), status text not null default 'trial' check(status in ('trial','active','past_due')), trial_ends_at timestamptz, next_billing_at timestamptz, monthly_price_kobo bigint not null default 0 check(monthly_price_kobo>=0), bundle_balance integer not null default 0 check(bundle_balance>=0), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.billing_offers (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), offer_key text not null, name text not null, kind text not null check(kind in ('monthly','yearly','volume','bundle')), price_kobo bigint not null check(price_kobo>=0), conversations integer not null check(conversations>0), description text not null default '', active boolean not null default true, unique(vendor_id,offer_key), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.billing_selections (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), unique(vendor_id), offer_id uuid not null, foreign key(vendor_id,offer_id) references public.billing_offers(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.usage_meters (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), period_start timestamptz not null, period_end timestamptz not null, conversations integer not null default 0 check(conversations>=0), conversation_limit integer not null check(conversation_limit>=0), check(period_end>period_start), unique(vendor_id,period_start), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.usage_entries (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), meter_id uuid not null, conversation_id uuid, quantity integer not null check(quantity>0), dedupe_key text not null, unique(vendor_id,dedupe_key), foreign key(vendor_id,meter_id) references public.usage_meters(vendor_id,id), foreign key(vendor_id,conversation_id) references public.conversations(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.payments (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), order_id uuid not null, source text not null check(source in ('vendor','paystack')), amount_kobo bigint not null check(amount_kobo>0), reference text not null, verified_at timestamptz not null, verified_by uuid, unique(vendor_id,source,reference), foreign key(vendor_id,order_id) references public.orders(vendor_id,id), foreign key(vendor_id,verified_by) references public.vendor_members(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.stock_reservations (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), order_id uuid not null, order_item_id uuid not null, product_id uuid not null, variant_id uuid, quantity integer not null check(quantity>0), status text not null default 'active' check(status in ('active','committed','released','expired')), expires_at timestamptz not null, foreign key(vendor_id,order_id) references public.orders(vendor_id,id), foreign key(vendor_id,order_item_id) references public.order_items(vendor_id,id), foreign key(vendor_id,product_id) references public.products(vendor_id,id), foreign key(vendor_id,product_id,variant_id) references public.product_variants(vendor_id,product_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.stock_movements (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), product_id uuid not null, variant_id uuid, order_id uuid, requested integer not null check(requested>0), delta integer not null check(delta<>0), shortfall integer not null default 0 check(shortfall>=0), reason text not null check(reason in ('sale','restock','correction','release')), dedupe_key text not null, unique(vendor_id,dedupe_key), foreign key(vendor_id,product_id) references public.products(vendor_id,id), foreign key(vendor_id,product_id,variant_id) references public.product_variants(vendor_id,product_id,id), foreign key(vendor_id,order_id) references public.orders(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.order_timeline (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), order_id uuid not null, label text not null, customer_message_id uuid, occurred_at timestamptz not null default now(), foreign key(vendor_id,order_id) references public.orders(vendor_id,id), foreign key(vendor_id,customer_message_id) references public.messages(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.message_deliveries (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), message_id uuid not null, channel_account_id uuid not null, provider_message_id text, status text not null default 'queued' check(status in ('queued','sending','sent','delivered','read','failed')), attempt integer not null default 0 check(attempt>=0), error_code text, sent_at timestamptz, delivered_at timestamptz, read_at timestamptz, dedupe_key text not null, unique(vendor_id,dedupe_key), unique(vendor_id,channel_account_id,provider_message_id), foreign key(vendor_id,message_id) references public.messages(vendor_id,id), foreign key(vendor_id,channel_account_id) references public.channel_accounts(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.webhook_events (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), channel_account_id uuid, provider text not null check(provider in ('whatsapp','instagram','facebook','tiktok','email','paystack')), provider_event_id text not null, payload_ciphertext bytea not null check(octet_length(payload_ciphertext)>16), key_version text not null, payload_hash text not null check(payload_hash ~ '^[0-9a-f]{64}$'), signature_verified boolean not null check(signature_verified), received_at timestamptz not null default now(), processed_at timestamptz, expires_at timestamptz not null, unique(vendor_id,provider,provider_event_id), foreign key(vendor_id,channel_account_id) references public.channel_accounts(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.jobs (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), kind text not null check(kind in ('ingest','send','holding_reply','followup','restock','payment','receipt','usage')), webhook_event_id uuid, conversation_id uuid, message_id uuid, order_id uuid, status text not null default 'queued' check(status in ('queued','running','succeeded','failed','dead')), run_at timestamptz not null default now(), locked_until timestamptz, attempts integer not null default 0 check(attempts>=0), max_attempts integer not null default 5 check(max_attempts>0), dedupe_key text not null, last_error_code text, unique(vendor_id,kind,dedupe_key), foreign key(vendor_id,webhook_event_id) references public.webhook_events(vendor_id,id), foreign key(vendor_id,conversation_id) references public.conversations(vendor_id,id), foreign key(vendor_id,message_id) references public.messages(vendor_id,id), foreign key(vendor_id,order_id) references public.orders(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.idempotency_keys (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), operation text not null, actor_scope text not null, key_hash text not null check(key_hash ~ '^[0-9a-f]{64}$'), request_hash text not null check(request_hash ~ '^[0-9a-f]{64}$'), status text not null default 'in_progress' check(status in ('in_progress','completed')), response_ciphertext bytea, key_version text, http_status integer check(http_status between 100 and 599), resource_id uuid, expires_at timestamptz not null, unique(vendor_id,actor_scope,operation,key_hash), check(status<>'completed' or (response_ciphertext is not null and key_version is not null and http_status is not null)), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.receipt_shares (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), receipt_id uuid not null, token_hash text not null check(token_hash ~ '^[0-9a-f]{64}$'), expires_at timestamptz not null, revoked_at timestamptz, unique(token_hash), foreign key(vendor_id,receipt_id) references public.receipts(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

create table public.domain_events (id uuid primary key default gen_random_uuid(), vendor_id uuid not null references public.vendors(id), event_type text not null check(event_type in ('message_received','reply_sent','approval_created','approval_decided','lead_stage_changed','order_created','order_paid','order_status_changed','receipt_issued','stock_changed','takeover_started','takeover_ended','followup_sent','restock_notified','channel_connected','customer_identity_linked','payment_verified')), occurred_at timestamptz not null default now(), recorded_at timestamptz not null default now(), actor_member_id uuid, conversation_id uuid, message_id uuid, customer_id uuid, order_id uuid, product_id uuid, from_stage text check(from_stage in ('new','interested','ready_to_pay','paid','cold')), to_stage text check(to_stage in ('new','interested','ready_to_pay','paid','cold')), correlation_id uuid not null default gen_random_uuid(), dedupe_key text not null, unique(vendor_id,dedupe_key), check(event_type<>'lead_stage_changed' or (conversation_id is not null and to_stage is not null and from_stage is distinct from to_stage)), foreign key(vendor_id,actor_member_id) references public.vendor_members(vendor_id,id), foreign key(vendor_id,conversation_id) references public.conversations(vendor_id,id), foreign key(vendor_id,message_id) references public.messages(vendor_id,id), foreign key(vendor_id,customer_id) references public.customers(vendor_id,id), foreign key(vendor_id,order_id) references public.orders(vendor_id,id), foreign key(vendor_id,product_id) references public.products(vendor_id,id), created_at timestamptz not null default now(), unique(vendor_id,id));

insert into public.business_settings(vendor_id) select id from public.vendors;
insert into public.business_hours(vendor_id,day,closed) select v.id,d,d=0 from public.vendors v cross join generate_series(0,6) d;
insert into public.followup_settings(vendor_id) select id from public.vendors;
insert into public.member_preferences(vendor_id,member_id) select vendor_id,id from public.vendor_members;
-- Composite relationship strengthening (same vendor is necessary, same parent is also enforced).
alter table public.conversations add unique(vendor_id,customer_id,id);
alter table public.followups add foreign key(vendor_id,customer_id,conversation_id) references public.conversations(vendor_id,customer_id,id);
alter table public.order_items add unique(vendor_id,order_id,id);
alter table public.stock_reservations add foreign key(vendor_id,order_id,order_item_id) references public.order_items(vendor_id,order_id,id);
create unique index active_invitation_email on public.team_invitations(vendor_id,email) where status='pending';
create unique index current_channel_attempt on public.channel_attempts(vendor_id,channel_account_id) where status='pending';
create unique index current_helper_link on public.helper_links(vendor_id) where status in ('pending','linked');
create unique index waiting_restock_variant on public.restock_requests(vendor_id,customer_id,product_id,variant_id) where status='waiting' and variant_id is not null;
create unique index waiting_restock_product on public.restock_requests(vendor_id,customer_id,product_id) where status='waiting' and variant_id is null;
create unique index active_order_reservation on public.stock_reservations(vendor_id,order_item_id) where status='active';
create unique index payment_reference_unique on public.orders(vendor_id,payment_source,payment_reference) where payment_reference is not null;
create index inbox_cursor on public.conversations(vendor_id,updated_at desc,id desc);
create index inbox_channel_cursor on public.conversations(vendor_id,channel_account_id,updated_at desc,id desc);
create index inbox_stage_cursor on public.conversations(vendor_id,stage,updated_at desc,id desc);
create index inbox_assignee_cursor on public.conversations(vendor_id,assigned_member_id,updated_at desc,id desc);
create index orders_cursor on public.orders(vendor_id,created_at desc,id desc);
create index orders_status_cursor on public.orders(vendor_id,status,created_at desc,id desc);
create index orders_customer_cursor on public.orders(vendor_id,customer_id,created_at desc,id desc);
create index thread_cursor on public.messages(vendor_id,conversation_id,created_at desc,id desc);
create index approvals_pending_cursor on public.approvals(vendor_id,status,created_at desc,id desc);
create index approvals_holding_due on public.approvals(vendor_id,holding_reply_due_at,id) where status='pending' and holding_reply_sent_at is null;
create index receipts_cursor on public.receipts(vendor_id,issued_at desc,id desc);
create index customers_cursor on public.customers(vendor_id,created_at desc,id desc);
create index catalogue_cursor on public.products(vendor_id,archived,category,created_at desc,id desc);
create index events_funnel on public.domain_events(vendor_id,conversation_id,occurred_at,id);
create index events_cursor on public.domain_events(vendor_id,recorded_at,id);
create index events_type_time on public.domain_events(vendor_id,event_type,occurred_at,id);
create index followups_due on public.followups(vendor_id,scheduled_at,id) where status='scheduled';
create index jobs_due on public.jobs(vendor_id,run_at,id) where status in ('queued','failed');
create index jobs_leases on public.jobs(vendor_id,locked_until,id) where status='running';
create index notifications_cursor on public.notifications(vendor_id,member_id,created_at desc,id desc);
create index notifications_unread on public.notifications(vendor_id,member_id,created_at desc,id desc) where read_at is null;
create index reservations_expiry on public.stock_reservations(vendor_id,expires_at,id) where status='active';
create index webhook_retention on public.webhook_events(vendor_id,expires_at,id);
create index idempotency_expiry on public.idempotency_keys(vendor_id,expires_at,id);

do $$ declare r record; begin for r in select tablename,policyname from pg_policies where schemaname='public' and tablename=any(array['vendors','vendor_members','customers','conversations','products','product_variants','orders','order_items','messages','approvals','channel_accounts','receipts','audit_log','business_settings','business_hours','delivery_fees','followup_settings','member_preferences','conversation_reads','product_photos','catalogue_drafts','typed_proposals','team_invitations','followups','moderation_flags','blocked_identities','restock_requests','customer_identities','notifications','billing_accounts','billing_offers','billing_selections','usage_meters','payments','stock_movements','usage_entries','domain_events','stock_reservations','order_timeline','message_deliveries','channel_tokens','channel_attempts','helper_links','invitation_secrets','webhook_events','jobs','idempotency_keys','receipt_shares']) loop execute format('drop policy %I on public.%I',r.policyname,r.tablename); end loop; end $$;
alter table public.vendors enable row level security; alter table public.vendors force row level security;
revoke all on public.vendors from public,anon,authenticated,service_role,selvora_service;
grant select on public.vendors to authenticated;
create policy b0_r on public.vendors for select to authenticated using (public.has_vendor_role(vendor_id,array['owner','manager','agent']));
grant select on public.vendors to selvora_service;
create policy worker_r on public.vendors for select to selvora_service using (public.service_vendor(vendor_id));
grant update on public.vendors to authenticated;
create policy b0_u on public.vendors for update to authenticated using (public.has_vendor_role(vendor_id,array['owner'])) with check (public.has_vendor_role(vendor_id,array['owner']));
grant update on public.vendors to selvora_service;
create policy worker_u on public.vendors for update to selvora_service using (public.service_vendor(vendor_id)) with check (public.service_vendor(vendor_id));
