-- Table REVOKE does not remove F0 column-specific grants. Remove those explicitly too.
revoke insert(vendor_id,customer_id,status,total_kobo,delivery_fee_kobo,delivery_city), update(status,total_kobo,delivery_fee_kobo,delivery_city) on public.orders from authenticated;
create or replace function public.is_vendor_member(p_vendor uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.vendor_members where vendor_id=p_vendor and user_id=auth.uid() and status='active'); $$;
create or replace function public.has_vendor_role(p_vendor uuid,p_roles text[]) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.vendor_members where vendor_id=p_vendor and user_id=auth.uid() and status='active' and role=any(p_roles)); $$;
-- No human tenant_id reassignment, agent assignment or arbitrary preference notifications.
create function public.b0_guard_human_update() returns trigger language plpgsql set search_path='' as $$
begin
 if current_user='authenticated' then
  if new.vendor_id<>old.vendor_id or new.id<>old.id then raise exception 'Immutable identity' using errcode='42501'; end if;
  if tg_table_name='conversations' then
   if (to_jsonb(new)-array['human_mode','human_mode_until']) is distinct from (to_jsonb(old)-array['human_mode','human_mode_until']) then raise exception 'Use authorized conversation transaction' using errcode='42501'; end if;
  end if;
  if tg_table_name='notifications' then
   if (to_jsonb(new)-'read_at') is distinct from (to_jsonb(old)-'read_at') then raise exception 'Read marker only' using errcode='42501'; end if;
  end if;
 end if;
 return new;
end $$;
create trigger human_update_guard before update on public.vendors for each row execute function public.b0_guard_human_update();
create trigger human_update_guard before update on public.customers for each row execute function public.b0_guard_human_update();
create trigger human_update_guard before update on public.conversations for each row execute function public.b0_guard_human_update();
create trigger human_update_guard before update on public.products for each row execute function public.b0_guard_human_update();
create trigger human_update_guard before update on public.product_variants for each row execute function public.b0_guard_human_update();
create trigger human_update_guard before update on public.business_settings for each row execute function public.b0_guard_human_update();
create trigger human_update_guard before update on public.business_hours for each row execute function public.b0_guard_human_update();
create trigger human_update_guard before update on public.delivery_fees for each row execute function public.b0_guard_human_update();
create trigger human_update_guard before update on public.followup_settings for each row execute function public.b0_guard_human_update();
create trigger human_update_guard before update on public.member_preferences for each row execute function public.b0_guard_human_update();
create trigger human_update_guard before update on public.conversation_reads for each row execute function public.b0_guard_human_update();
create trigger human_update_guard before update on public.product_photos for each row execute function public.b0_guard_human_update();
create trigger human_update_guard before update on public.catalogue_drafts for each row execute function public.b0_guard_human_update();
