-- Financial RPCs from F0 remain guarded; generic table DML is not granted to humans.
-- Replace payment RPC with owner/manager authorization and a one-time audit record.
create or replace function public.confirm_vendor_payment(p_vendor uuid,p_order uuid) returns void language plpgsql security definer set search_path='' as $$
begin
 if not public.has_vendor_role(p_vendor,array['owner','manager']) then raise exception 'Forbidden' using errcode='42501'; end if;
 update public.orders set payment_status='paid',payment_source='vendor',paid_at=now(),status='paid',revision=revision+1 where vendor_id=p_vendor and id=p_order and payment_status='unpaid' and status='awaiting_payment';
 if found then insert into public.audit_log(vendor_id,actor_id,action,entity_type,entity_id) values(p_vendor,auth.uid(),'payment.vendor_confirmed','order',p_order);
 elsif not exists(select 1 from public.orders where vendor_id=p_vendor and id=p_order and payment_status='paid') then raise exception 'Awaiting unpaid order required' using errcode='23514'; end if;
end $$;
-- Receipt RPC previously allowed any member. Preserve snapshots/numbers, tighten authorization.
alter function public.issue_receipt(uuid,uuid) rename to b0_issue_receipt_internal;
revoke all on function public.b0_issue_receipt_internal(uuid,uuid) from public,authenticated,anon,service_role,selvora_service;
create function public.issue_receipt(p_vendor uuid,p_order uuid) returns uuid language plpgsql security definer set search_path='' as $$ begin
 if not public.has_vendor_role(p_vendor,array['owner','manager']) then raise exception 'Forbidden' using errcode='42501'; end if;
 return public.b0_issue_receipt_internal(p_vendor,p_order);
end $$;
revoke all on function public.issue_receipt(uuid,uuid) from public;
grant execute on function public.issue_receipt(uuid,uuid) to authenticated;
-- Index every composite FK's child lookup (incl. nullable references); avoid extension dependencies.
do $$ declare r record; cols text; begin
 for r in select c.conrelid::regclass as tbl,c.conname,c.conkey from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname='public' and c.contype='f' and c.conrelid=any(array['public.vendors'::regclass,'public.vendor_members'::regclass,'public.customers'::regclass,'public.conversations'::regclass,'public.products'::regclass,'public.product_variants'::regclass,'public.orders'::regclass,'public.order_items'::regclass,'public.messages'::regclass,'public.approvals'::regclass,'public.channel_accounts'::regclass,'public.receipts'::regclass,'public.audit_log'::regclass,'public.business_settings'::regclass,'public.business_hours'::regclass,'public.delivery_fees'::regclass,'public.followup_settings'::regclass,'public.member_preferences'::regclass,'public.conversation_reads'::regclass,'public.product_photos'::regclass,'public.catalogue_drafts'::regclass,'public.typed_proposals'::regclass,'public.team_invitations'::regclass,'public.followups'::regclass,'public.moderation_flags'::regclass,'public.blocked_identities'::regclass,'public.restock_requests'::regclass,'public.customer_identities'::regclass,'public.notifications'::regclass,'public.billing_accounts'::regclass,'public.billing_offers'::regclass,'public.billing_selections'::regclass,'public.usage_meters'::regclass,'public.payments'::regclass,'public.stock_movements'::regclass,'public.usage_entries'::regclass,'public.domain_events'::regclass,'public.stock_reservations'::regclass,'public.order_timeline'::regclass,'public.message_deliveries'::regclass,'public.channel_tokens'::regclass,'public.channel_attempts'::regclass,'public.helper_links'::regclass,'public.invitation_secrets'::regclass,'public.webhook_events'::regclass,'public.jobs'::regclass,'public.idempotency_keys'::regclass,'public.receipt_shares'::regclass]) loop
 select string_agg(quote_ident(a.attname),',' order by k.ord) into cols from unnest(r.conkey) with ordinality k(num,ord) join pg_attribute a on a.attrelid=r.tbl and a.attnum=k.num;
 if not exists(
  select 1 from pg_index i join pg_class ix on ix.oid=i.indexrelid join pg_am am on am.oid=ix.relam
  where i.indrelid=r.tbl and i.indisvalid and i.indpred is null and am.amname='btree'
  and (select array_agg(k.attnum::smallint order by k.ord) from unnest(i.indkey) with ordinality k(attnum,ord) where k.ord<=cardinality(r.conkey))=r.conkey
 ) then
  execute format('create index %I on %s(%s)',left('b0_fk_'||r.conname||'_'||r.tbl::oid,63),r.tbl,cols);
 end if;
 end loop;
end $$;
commit;
